#include <Cellerator/compiler/profile/implement_profile_selection_and_binding_v1.hh>
namespace cellerator::compiler::profile::v1 { namespace {template<class I>bool same(I a,I b){return a.low==b.low&&a.high==b.high;}template<class I>bool zero(I a){return a.low==0&&a.high==0;}}
profile_binding_status_v1 bind_profile_v1(const profile_binding_request_v1&r,bound_profile_v1*out) noexcept{if(!out||(r.profile_count&&!r.profiles))return profile_binding_status_v1::invalid_argument;if(r.pure_cxx||!r.semantic_activation){*out={r.symbol,r.field,{},{},false,true};return profile_binding_status_v1::pure_cxx_fallthrough;}const available_profile_v1*chosen=nullptr;for(std::uint32_t i=0;i<r.profile_count;++i){auto&p=r.profiles[i];bool identity= same(p.domain,r.required_domain)&&same(p.axis,r.required_axis);if(!identity)continue;if(p.generic_reference&&!r.allow_generic_reference)continue;if(chosen)return profile_binding_status_v1::ambiguous_profile;chosen=&p;}if(!chosen)return r.profile_count?profile_binding_status_v1::identity_mismatch:profile_binding_status_v1::missing_profile;if(!chosen->environment)return profile_binding_status_v1::invalid_argument;const named_profile_state_v1*s=zero(r.requested_name)?default_named_profile_state_v1(*chosen->environment):find_named_profile_state_v1(*chosen->environment,r.requested_name);if(!s)return profile_binding_status_v1::name_not_found;*out={r.symbol,r.field,chosen->artifact,s->state,chosen->generic_reference,false};return profile_binding_status_v1::ok;}
}  // namespace cellerator::compiler::profile::v1
